100	// Validate and retrieve OAuth state from storage (CSRF protection)
101	// Returns identityProviderName, flowMode, returnUrl, linkingUserName, and codeVerifier for PKCE
102	export function validateOAuthState(
103	  stateParam: string,
104	): { identityProviderName: string; flowMode: OAuthFlowMode; returnUrl?: string; linkingUserName?: string; codeVerifier?: string } | null {
105	  try {
106	    const storedData = sessionStorage.getItem(STATE_STORAGE_KEY);
107	    if (!storedData) {
108	      console.error("No OAuth state found in storage");
109	      return null;
110	    }
111	
112	    const stateData: OAuthState = JSON.parse(storedData);
113	
114	    // Check if state has expired
115	    if (Date.now() - stateData.timestamp > STATE_EXPIRY_MS) {
116	      console.error("OAuth state has expired");
117	      sessionStorage.removeItem(STATE_STORAGE_KEY);
118	      return null;
119	    }
120	
