131	      identityProviderName: stateData.identityProviderName,
132	      flowMode: stateData.flowMode || "signin",
133	      returnUrl: stateData.returnUrl,
134	      linkingUserName: stateData.linkingUserName,
135	      codeVerifier: stateData.codeVerifier, // Return PKCE code_verifier
136	    };
137	  } catch (error) {
138	    console.error("Failed to validate OAuth state:", error);
139	    sessionStorage.removeItem(STATE_STORAGE_KEY);
140	    return null;
141	  }
142	}
